+/** Selects the highest-quality supported request language, or the configured fallback. */
+export function requestLanguage(header, fallback = "en") {
+  if (typeof header !== "string") return fallback;
+  let selected = fallback;
+  let bestQuality = 0;
+  for (const entry of header.split(",")) {
+    const [tag, ...parameters] = entry.trim().split(";");
+    if (!/^[a-z]{2}(?:-[a-z0-9]{1,8})*$/i.test(tag)) continue;
+    const language = tag.toLowerCase().split("-")[0];
+    if (!LANGUAGES.includes(language)) continue;
+    let quality = 1;
+    for (const parameter of parameters) {
+      const match = /^q\s*=\s*(0(?:\.\d{0,3})?|1(?:\.0{0,3})?)$/i.exec(parameter.trim());
+      if (!match) {
+        quality = 0;
+        break;
+      }
+      quality = Number(match[1]);
+    }
+    if (quality > bestQuality) {
+      selected = language;
+      bestQuality = quality;
+    }
+  }
+  return selected;
+}
